// Run the loop once for each item
for (size_t item_index = 0; item_index < w.size(); ++item_index) {
    // Compare and change values
    for (int index = 0; index <= capacity; ++index) {
        // You can only add an item if the bag size
        // is larger than the item weight
        if (index >= w[item_index]) {
            DP[item_index + 1][index] = max(
                DP[item_index][index], 
                DP[item_index][index - w[item_index]] + v[item_index]
            );
        } 
        // Otherwise, just copy the profit from one row above
        else {
            DP[item_index + 1][index] = DP[item_index][index];
        }
    }
}
